card(id="microcontrollore", name="Microcontrollore", aka="es. ATmega328P di Arduino Uno, RP2040", area="mcu", sub="microcontrollori",
     principles=["programma"], related=["adc", "pwm", "esp32"],
     hook="Un piccolo computer in un solo chip: legge sensori, decide, comanda",
     short="Dentro un solo chip ci sono un processore, la memoria per il programma, la memoria di lavoro e tante periferiche: piedini di ingresso e uscita, convertitori, timer, porte seriali. Il programma gira in un ciclo continuo: legge gli ingressi, decide che cosa fare e cambia le uscite, migliaia di volte al secondo.",
     steps=["Il programma, scritto al computer (per esempio con Arduino), viene caricato nella memoria flash del chip e ci resta anche senza alimentazione.",
            "All'accensione il processore esegue le istruzioni una dopo l'altra, al ritmo dell'oscillatore al quarzo (16 milioni di passi al secondo in un Arduino Uno).",
            "Un piedino configurato come ingresso legge se c'è tensione (1) o no (0); uno come uscita mette 5 V o 0 V e può accendere un LED.",
            "Il ciclo ricomincia subito: così il chip reagisce a un pulsante in una frazione di millisecondo."],
     formula="ATmega328P: 16 MHz · 32 KB di flash · 2 KB di RAM · uscite fino a circa 20 mA per piedino",
     variants=[{"name": "AVR (Arduino Uno, Nano)", "text": "8 bit, semplici e robusti, logica a 5 V."},
               {"name": "ARM (RP2040, STM32)", "text": "32 bit, molto più veloci, logica a 3,3 V."},
               {"name": "Con radio (ESP32)", "text": "Aggiungono Wi-Fi e Bluetooth nello stesso chip."}],
     note="Un microcontrollore non è un computer come un Raspberry Pi: non ha sistema operativo, fa una cosa sola, parte in un attimo e consuma pochissimo. Le uscite non alimentano motori o relè direttamente: servono un transistor o un driver.",
     uses=["Elettrodomestici, telecomandi, giocattoli", "Arduino e progetti fai-da-te", "Centraline delle auto"],
     diagram="microcontrollore",
     images=IMAGES.get("microcontrollore", []),
     source={"title": "Wikipedia – Microcontrollore", "url": "https://it.wikipedia.org/wiki/Microcontrollore"},
     quiz=[{"q": "Che cosa c'è dentro un microcontrollore, oltre al processore?", "options": ["Memorie e periferiche di ingresso/uscita", "Solo il processore", "Un sistema operativo completo", "Uno schermo"], "correct": 0,
            "expl": "Processore, memoria del programma, RAM e periferiche (piedini, ADC, timer, seriali) stanno nello stesso chip."},
           {"q": "Perché non si collega un motore direttamente a un piedino di uscita?", "options": ["Il piedino dà solo pochi milliampere", "Perché il motore è troppo veloce", "Perché il motore è digitale", "Si può fare senza problemi"], "correct": 0,
            "expl": "Un piedino regge circa 20 mA: per motori e relè serve un transistor o un driver che faccia da interruttore."}])

card(id="adc", name="Convertitore analogico-digitale", aka="ADC", area="mcu", sub="periferiche",
     principles=["campionamento", "quantizzazione"], related=["microcontrollore", "potenziometro", "ntc"],
     hook="Trasforma una tensione in un numero che il programma può usare",
     short="I sensori danno tensioni che variano con continuità; il processore capisce solo numeri. L'ADC misura la tensione e la traduce in un numero intero tra 0 e un massimo. Con 10 bit e riferimento a 5 V, come in Arduino Uno, i gradini sono 1024: ognuno vale circa 4,9 millivolt.",
     steps=["L'ADC prende un campione: \"fotografa\" la tensione del piedino in un istante.",
            "La confronta con una tensione di riferimento (per esempio 5 V) e trova in quale gradino cade.",
            "Il risultato è un numero: 0 per 0 V, circa 512 a metà, 1023 al massimo.",
            "Ripetendo la misura tante volte al secondo il programma segue come cambia il segnale."],
     formula="numero = tensione × 1024 ÷ riferimento (massimo 1023) · gradino = 5 V ÷ 1024 ≈ 4,9 mV",
     variants=[{"name": "Integrato nel microcontrollore", "text": "10 bit su Arduino Uno, 12 bit su ESP32 e STM32."},
               {"name": "Esterno (es. ADS1115)", "text": "16 bit e ingressi differenziali, collegato via I²C."},
               {"name": "Veloci", "text": "Milioni di campioni al secondo per audio, radio e oscilloscopi."}],
     note="La tensione sul piedino non deve mai superare quella del riferimento (né quella di alimentazione del chip): con sensori che danno più tensione si usa un partitore.",
     uses=["Leggere potenziometri, fotoresistenze, termistori", "Misurare la tensione della batteria", "Registrare suoni"],
     diagram="adc",
     images=IMAGES.get("adc", []),
     source={"title": "Wikipedia – Convertitore analogico-digitale", "url": "https://it.wikipedia.org/wiki/Convertitore_analogico-digitale"},
     quiz=[{"q": "Con un ADC a 10 bit e riferimento 5 V, che numero dà una tensione di 2,5 V?", "options": ["512", "250", "1023", "10"], "correct": 0,
            "expl": "2,5 × 1024 ÷ 5 = 512: metà della scala."},
           {"q": "Quanti gradini ha un ADC a 12 bit?", "options": ["4096", "1024", "12", "256"], "correct": 0,
            "expl": "2 elevato alla 12 = 4096 valori possibili."}])

card(id="pwm", name="PWM", aka="modulazione a larghezza d'impulso", area="mcu", sub="periferiche",
     principles=["modulazione-pwm"], related=["microcontrollore", "led", "driver-ponte-h"],
     hook="Accendi e spegni in fretta: così un'uscita digitale fa anche le mezze misure",
     short="Un piedino digitale può stare solo a 5 V o a 0 V. Ma se lo accendi e lo spegni centinaia di volte al secondo, un LED o un motore \"sentono\" la media. Cambiando la frazione di tempo in cui l'uscita è accesa (il duty cycle) cambi la luminosità o la velocità. In Arduino si scrive con analogWrite, da 0 a 255.",
     steps=["Un timer del microcontrollore ripete un ciclo fisso, per esempio circa 490 volte al secondo.",
            "In ogni ciclo l'uscita resta accesa per una parte del tempo e spenta per il resto.",
            "Al 25 % la media è un quarto di 5 V; al 100 % è sempre accesa.",
            "L'occhio non vede il lampeggio (è troppo veloce) e un motore, con la sua inerzia, gira a velocità intermedia."],
     formula="tensione media ≈ duty cycle × 5 V · analogWrite(valore): duty = valore ÷ 255",
     variants=[{"name": "LED", "text": "Luminosità regolabile senza sprecare energia in resistenze."},
               {"name": "Motori", "text": "Con un transistor o un ponte H: velocità regolabile."},
               {"name": "Servo", "text": "Un caso speciale: conta la durata dell'impulso (1–2 ms) ogni 20 ms."}],
     note="La PWM non è una vera tensione intermedia: per un carico che ha bisogno di tensione continua si aggiunge un filtro (resistenza e condensatore).",
     uses=["Regolare la luce di LED e strisce", "Velocità di motori e ventole", "Convertitori step-up e step-down"],
     diagram="pwm",
     images=IMAGES.get("pwm", []),
     source={"title": "Wikipedia – Modulazione di larghezza d'impulso", "url": "https://it.wikipedia.org/wiki/Modulazione_di_larghezza_d%27impulso"},
     quiz=[{"q": "Con analogWrite(64) su un'uscita a 5 V, qual è circa la tensione media?", "options": ["1,25 V", "2,5 V", "64 V", "0,64 V"], "correct": 0,
            "expl": "64 ÷ 255 ≈ 25 % del tempo accesa: 0,25 × 5 V ≈ 1,25 V di media."},
           {"q": "Perché non si vede il LED lampeggiare con la PWM?", "options": ["Lampeggia troppo in fretta per l'occhio", "Perché la tensione è costante", "Perché il LED si scalda", "Perché è spento"], "correct": 0,
            "expl": "Centinaia di accensioni al secondo si fondono: l'occhio percepisce la luminosità media."}])

card(id="uart", name="Seriale UART", aka="TX / RX", area="interfacce", sub="bus-seriali",
     principles=["trasmissione-seriale"], related=["microcontrollore", "i2c", "spi"],
     hook="Due fili incrociati e una velocità concordata: la conversazione più semplice tra chip",
     short="Chi trasmette manda i bit uno dopo l'altro sul suo piedino TX, che è collegato al piedino RX dell'altro (e viceversa). Non c'è un filo di clock: entrambi devono usare la stessa velocità, per esempio 9600 bit al secondo. Ogni carattere parte con un bit di start, poi 8 bit di dati (dal meno significativo) e un bit di stop.",
     steps=["A riposo la linea sta alta (1).",
            "Il bit di start la porta bassa per la durata di un bit: il ricevitore capisce che arriva un carattere e si sincronizza.",
            "Seguono 8 bit di dati, a intervalli fissi: a 9600 baud ogni bit dura circa 104 microsecondi.",
            "Il bit di stop riporta la linea alta. Il ricevitore ha in mano il carattere."],
     formula="durata di un bit = 1 ÷ velocità · 9600 baud → circa 104 µs per bit",
     variants=[{"name": "USB-seriale", "text": "Il chip che fa parlare Arduino con il computer (Serial Monitor)."},
               {"name": "RS-232 / RS-485", "text": "Stessa idea con tensioni diverse, per distanze più lunghe."},
               {"name": "Moduli", "text": "GPS, Bluetooth HC-05, sensori di polveri: tanti parlano in seriale."}],
     note="TX va sempre su RX e RX su TX, con la massa in comune. Attenzione ai livelli: un modulo a 3,3 V può rovinarsi ricevendo 5 V su RX.",
     uses=["Serial Monitor di Arduino", "Moduli GPS e Bluetooth", "Debug di router e schede"],
     diagram="uart",
     images=IMAGES.get("uart", []),
     source={"title": "Wikipedia – Universal asynchronous receiver-transmitter", "url": "https://en.wikipedia.org/wiki/Universal_asynchronous_receiver-transmitter"},
     quiz=[{"q": "Come si collegano due dispositivi in seriale UART?", "options": ["TX con RX, RX con TX, masse in comune", "TX con TX e RX con RX", "Solo con il filo di clock", "Basta un filo"], "correct": 0,
            "expl": "Ognuno trasmette sul suo TX e riceve sul suo RX: i fili vanno incrociati."},
           {"q": "Perché entrambi devono usare la stessa velocità (baud rate)?", "options": ["Non c'è un clock: i bit si leggono a tempi fissi", "Per consumare meno", "Perché lo vuole l'USB", "Non serve"], "correct": 0,
            "expl": "Senza clock, il ricevitore campiona la linea a intervalli calcolati sulla velocità concordata."}])

card(id="i2c", name="Bus I²C", aka="IIC, TWI · SDA e SCL", area="interfacce", sub="bus-seriali",
     principles=["trasmissione-seriale"], related=["spi", "uart", "barometro"],
     hook="Due fili, tanti dispositivi: ognuno risponde solo al suo indirizzo",
     short="Usa due soli fili: SDA per i dati e SCL per il clock, più la massa. Molti dispositivi stanno sullo stesso bus, ognuno con un indirizzo (per esempio 0x76 un BMP280, 0x3C un piccolo display OLED). Il microcontrollore comincia ogni messaggio con l'indirizzo: risponde solo il dispositivo che lo riconosce.",
     steps=["Due resistenze di pull-up tengono SDA e SCL alte; i dispositivi possono solo tirarle a 0 V.",
            "Il controllore segnala l'inizio (SDA scende mentre SCL è alta), poi manda 7 bit di indirizzo e 1 bit che dice se vuole leggere o scrivere.",
            "A ogni impulso di SCL viene letto un bit di SDA.",
            "Il dispositivo con quell'indirizzo risponde tirando SDA a 0 per un bit (ACK, \"ci sono\"); poi si scambiano i dati."],
     formula="velocità tipiche: 100 kHz o 400 kHz · 7 bit di indirizzo → fino a 112 indirizzi utilizzabili",
     variants=[{"name": "Sensori", "text": "Temperatura, pressione, accelerometri, luce: quasi tutti hanno l'I²C."},
               {"name": "Display", "text": "Piccoli OLED e LCD con modulo I²C."},
               {"name": "Qwiic / STEMMA QT", "text": "Connettori a 4 poli per collegare moduli in catena senza saldare."}],
     note="Due dispositivi con lo stesso indirizzo sullo stesso bus vanno in conflitto: molti moduli hanno un ponticello per cambiarlo. Senza pull-up il bus non funziona (molti moduli le hanno già).",
     uses=["Collegare più sensori con 2 fili", "Display OLED", "Orologi in tempo reale (RTC)"],
     diagram="i2c",
     images=IMAGES.get("i2c", []),
     source={"title": "Wikipedia – I²C", "url": "https://it.wikipedia.org/wiki/I%C2%B2C"},
     quiz=[{"q": "Come fa un dispositivo I²C a sapere che il messaggio è per lui?", "options": ["Riconosce il proprio indirizzo all'inizio del messaggio", "Ha un filo tutto suo", "Ascolta solo se è il primo", "Dal colore del filo"], "correct": 0,
            "expl": "Il controllore manda prima l'indirizzo: risponde (ACK) solo il dispositivo che lo riconosce."},
           {"q": "Quali sono i due fili dell'I²C?", "options": ["SDA (dati) e SCL (clock)", "TX e RX", "MOSI e MISO", "VCC e GND"], "correct": 0,
            "expl": "SDA porta i dati, SCL il clock che scandisce ogni bit."}])

card(id="spi", name="Bus SPI", aka="SCK, MOSI, MISO, CS", area="interfacce", sub="bus-seriali",
     principles=["trasmissione-seriale"], related=["i2c", "uart", "microcontrollore"],
     hook="Quattro fili e un clock veloce: si parla e si ascolta nello stesso istante",
     short="Il controllore genera il clock (SCK) e a ogni impulso manda un bit sul filo MOSI e ne riceve uno sul filo MISO: trasmissione e ricezione avvengono insieme. Ogni dispositivo ha un suo filo di selezione (CS): ascolta solo quando il suo CS viene portato a 0 V. È molto più veloce dell'I²C, ma usa più fili.",
     steps=["Il controllore porta a 0 V il CS del dispositivo con cui vuole parlare; gli altri restano zitti.",
            "A ogni impulso di SCK un bit esce su MOSI (dal controllore al dispositivo) e uno entra su MISO (dal dispositivo al controllore).",
            "Dopo 8 impulsi i due hanno scambiato un byte ciascuno, come due registri che si passano i bit in cerchio.",
            "Il controllore riporta alto il CS: la conversazione è finita."],
     formula="velocità tipiche: da 1 a decine di MHz · 3 fili comuni + 1 CS per dispositivo",
     variants=[{"name": "Schede SD", "text": "Le microSD si leggono in SPI dai microcontrollori."},
               {"name": "Display TFT", "text": "Lo SPI veloce serve a mandare tante immagini al secondo."},
               {"name": "Memorie flash", "text": "Il programma dell'ESP32 sta in una flash SPI."}],
     note="I nomi cambiano tra i produttori: MOSI/MISO si trovano anche come SDO/SDI o COPI/CIPO. Conta il verso: l'uscita del controllore va sull'ingresso del dispositivo.",
     uses=["Schede SD e memorie", "Display a colori", "Convertitori ADC veloci"],
     diagram="spi",
     images=IMAGES.get("spi", []),
     source={"title": "Wikipedia – Serial Peripheral Interface", "url": "https://en.wikipedia.org/wiki/Serial_Peripheral_Interface"},
     quiz=[{"q": "A che cosa serve il filo CS in SPI?", "options": ["A scegliere con quale dispositivo parlare", "A portare il clock", "A dare l'alimentazione", "A trasmettere i dati"], "correct": 0,
            "expl": "Ogni dispositivo ascolta solo quando il suo CS è basso."},
           {"q": "In SPI, mentre il controllore trasmette un byte, il dispositivo…", "options": ["ne trasmette uno nello stesso momento", "aspetta in silenzio", "si spegne", "cambia indirizzo"], "correct": 0,
            "expl": "MOSI e MISO lavorano insieme a ogni impulso di clock: è una trasmissione bidirezionale simultanea."}])

